#!/usr/bin/env bash
# Self-contained Linux8c retry: corrected final controls and timed own-lib only.
set -uo pipefail
export RUSTC_WRAPPER= CARGO_BUILD_RUSTC_WRAPPER= CARGO_BUILD_JOBS=8
while IFS= read -r name; do unset "$name"; done < <(compgen -A variable MC_)
scratch=target/scratch/s4-finish-preflight
mkdir -p "$scratch"
python3 - <<'S4_RETRY_PAYLOAD'
import base64,hashlib,json,zlib
from pathlib import Path
payload=json.loads(zlib.decompress(base64.b64decode("")))
root=Path('target/scratch/s4-finish-preflight')
for name,content in payload.items():
    path=root/name
    path.write_text(content)
    print('RETRY INPUT '+name+' sha256='+hashlib.sha256(path.read_bytes()).hexdigest(),flush=True)
S4_RETRY_PAYLOAD
failure=0
summary="$scratch/summary.txt"
: >"$summary"
run() {
  local name=$1
  shift
  echo "=== S4 RETRY STEP $name"
  "$@" 2>&1 | tee "$scratch/$name.log"
  local code=${PIPESTATUS[0]}
  echo "=== S4 RETRY RESULT $name $code"
  printf '%s %s\n' "$name" "$code" >>"$summary"
  if [ "$code" -ne 0 ]; then failure=1; fi
  return "$code"
}
cargo --version
rustc --version
python3 --version
git rev-parse HEAD
git status --short
run final-paired-baseline cargo test -p mc-module --lib final_same_ordinal_branches_refuse_ambiguity_and_return_exact_heads -- --nocapture --test-threads=1
baseline=$?
run final-anchors python3 "$scratch/s4-final-fix-mutations.py" --anchors
anchors=$?
if [ "$baseline" -eq 0 ] && [ "$anchors" -eq 0 ]; then
  run final-controls python3 "$scratch/s4-final-fix-mutations.py" || true
  run own-lib env -u MC_REVIEW_S4FINAL MC_S4FINAL_PROFILE=Broca MC_S4FINAL_RETENTION_MASTER_SEED=13174017127720468071 python3 "$scratch/s4-preflight-instrument.py" suite || true
else
  echo 'SKIPPED mutation and own-lib steps because baseline or anchors failed.'
fi
python3 - <<'S4_RETRY_SUMMARY'
from pathlib import Path
print('=== S4 RETRY SUMMARY')
print(Path('target/scratch/s4-finish-preflight/summary.txt').read_text(),end='')
S4_RETRY_SUMMARY
echo "=== S4 RETRY FINISHED $failure"
exit "$failure"
